(()=>{
const host=document.getElementById('refinedStage');if(!host)return;host.replaceChildren();host.setAttribute('aria-label','自动运转的多层行星齿轮机械线稿');const canvas=document.createElement('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','多层行星齿轮、传动轴和支架的自动运动线稿');host.append(canvas);const ctx=canvas.getContext('2d');let w=0,h=0,scale=1;
function resize(){w=host.clientWidth;h=host.clientHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);scale=Math.min(w/570,h/620)}new ResizeObserver(resize).observe(host);resize();const tau=Math.PI*2;
function project(x,y,z){const a=-.24,u=x*Math.cos(a)-y*Math.sin(a),v=x*Math.sin(a)+y*Math.cos(a);return[w/2+u*scale,h*.5+(v*.60-z*.86)*scale]}
function path(points,color='#98b8ac',width=.85,close=false){ctx.beginPath();for(let i=0;i<points.length;i++){const p=project(...points[i]);i?ctx.lineTo(...p):ctx.moveTo(...p)}if(close)ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function ring(x,y,z,r,color,width=1){const p=[];for(let i=0;i<=100;i++){const a=i/100*tau;p.push([x+Math.cos(a)*r,y+Math.sin(a)*r,z])}path(p,color,width)}function line(a,b,color,width){path([a,b],color,width)}
function gear(x,y,z,r,teeth,angle,color){for(const dz of[-7,7]){const p=[];for(let i=0;i<teeth*4;i++){const a=i/(teeth*4)*tau+angle,rr=r+(i%4===1||i%4===2?4:-2);p.push([x+Math.cos(a)*rr,y+Math.sin(a)*rr,z+dz])}path(p,color,.9,true)}for(let i=0;i<teeth;i+=2){const a=i/teeth*tau+angle;line([x+Math.cos(a)*(r+4),y+Math.sin(a)*(r+4),z-7],[x+Math.cos(a)*(r+4),y+Math.sin(a)*(r+4),z+7],color,.55)}ring(x,y,z+8,r*.70,color,.7);ring(x,y,z+8,r*.23,color);for(let i=0;i<6;i++){const a=angle+i*tau/6;line([x+Math.cos(a)*r*.27,y+Math.sin(a)*r*.27,z+8],[x+Math.cos(a)*r*.65,y+Math.sin(a)*r*.65,z+8],color,.7)}}
function draw(ms){requestAnimationFrame(draw);if(document.hidden||document.getElementById('home').hidden||!w)return;ctx.clearRect(0,0,w,h);const t=ms*.00018;
for(const z of[-145,135]){ring(0,0,z,211,'#47635a',1);ring(0,0,z,198,'#729185',1);ring(0,0,z,177,'#3c574d',.7);for(let i=0;i<16;i++){const a=i*tau/16;ring(Math.cos(a)*204,Math.sin(a)*204,z,3,'#8eaa98',.6)}}
for(let i=0;i<4;i++){const a=i*tau/4+.4,x=Math.cos(a)*204,y=Math.sin(a)*204;line([x,y,-145],[x,y,135],'#4e7163',.9);ring(x,y,140,8,'#a6bd9b');ring(x,y,-145,8,'#688373')}
for(const z of[-72,48]){ring(0,0,z,171,'#587a6b',.8);ring(0,0,z+14,171,'#7b9986',1);for(let i=0;i<64;i++){const a=i*tau/64;line([Math.cos(a)*163,Math.sin(a)*163,z+14],[Math.cos(a)*171,Math.sin(a)*171,z+14],'#607e6c',.65)}gear(0,0,z,58,24,-t*2,'#c5e895');for(let i=0;i<3;i++){const a=t+i*tau/3+(z<0?0:.65),x=Math.cos(a)*109,y=Math.sin(a)*109;gear(x,y,z,49,20,t*4+i*.3,'#91b6ab');ring(x,y,z+22,12,'#d0e8b5');line([0,0,z+24],[x,y,z+24],'#c0d78e',2);line([x,y,z-15],[x,y,z+28],'#9aba97',1.3)}ring(0,0,z+24,24,'#cde99f',1.2)}
ring(0,0,145,43,'#cce599',1.1);ring(0,0,155,43,'#719684');line([0,0,-175],[0,0,175],'#b2cc9b',2);for(let i=0;i<8;i++){const a=t*2+i*tau/8;line([Math.cos(a)*18,Math.sin(a)*18,-175],[Math.cos(a)*18,Math.sin(a)*18,175],'#567a65',.45)}ring(0,0,-175,18,'#a6c28e');ring(0,0,175,18,'#cee6a5')}
requestAnimationFrame(draw)
})();
